import{_ as l,a0 as p,w as o,s as r,ao as h,I as n,x as t,a1 as e,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"awk 系列：如何使用 awk 和正则表达式过滤文本或文件中的字符串 | LCTT x X-CMD","titleTemplate":false,"description":"awk 系列：如何使用 awk 和正则表达式过滤文本或文件中的字符串 | LCTT (awk) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"awk 系列：如何使用 awk 和正则表达式过滤文本或文件中的字符串 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"awk 系列：如何使用 awk 和正则表达式过滤文本或文件中的字符串 | LCTT (awk) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"awk/Part 1 - How to Use Awk and Regular Expressions to Filter Text or String in Files","title":"awk 系列：如何使用 awk 和正则表达式过滤文本或文件中的字符串","tag":"awk","desc":""},"relativePath":"awk/Part 1 - How to Use Awk and Regular Expressions to Filter Text or String in Files.md","filePath":"[post].md"}'),c={name:"awk/Part 1 - How to Use Awk and Regular Expressions to Filter Text or String in Files.md"};function d(k,a,g,w,u,b){const s=p("Link");return o(),r("div",null,[a[13]||(a[13]=h(`<h1 id="awk-系列-如何使用-awk-和正则表达式过滤文本或文件中的字符串" tabindex="-1">awk 系列：如何使用 awk 和正则表达式过滤文本或文件中的字符串 <a class="header-anchor" href="#awk-系列-如何使用-awk-和正则表达式过滤文本或文件中的字符串" aria-label="Permalink to “awk 系列：如何使用 awk 和正则表达式过滤文本或文件中的字符串”">​</a></h1><p><img src="http://www.tecmint.com/wp-content/uploads/2016/04/Linux-Awk-Command-Examples.png" alt=""></p><p>当我们在 Unix/Linux 下使用特定的命令从字符串或文件中读取或编辑文本时，我们经常需要过滤输出以得到感兴趣的部分。这时正则表达式就派上用场了。</p><h3 id="什么是正则表达式" tabindex="-1">什么是正则表达式? <a class="header-anchor" href="#什么是正则表达式" aria-label="Permalink to “什么是正则表达式?”">​</a></h3><p>正则表达式可以定义为代表若干个字符序列的字符串。它最重要的功能之一就是它允许你过滤一条命令或一个文件的输出、编辑文本或配置文件的一部分等等。</p><h3 id="正则表达式的特点" tabindex="-1">正则表达式的特点 <a class="header-anchor" href="#正则表达式的特点" aria-label="Permalink to “正则表达式的特点”">​</a></h3><p>正则表达式由以下内容组合而成：</p><ul><li><strong>普通字符</strong>，例如空格、下划线、A-Z、a-z、0-9。</li><li>可以扩展为普通字符的<strong>元字符</strong>，它们包括： <ul><li><code>(.)</code> 它匹配除了换行符外的任何单个字符。</li><li><code>(*)</code> 它匹配零个或多个在其之前紧挨着的字符。</li><li><code>[ character(s) ]</code> 它匹配任何由其中的字符/字符集指定的字符，你可以使用连字符(-)代表字符区间，例如 [a-f]、[1-5]等。</li><li><code>^</code> 它匹配文件中一行的开头。</li><li><code>$</code> 它匹配文件中一行的结尾。</li><li><code>\\</code> 这是一个转义字符。</li></ul></li></ul><p>你必须使用类似 awk 这样的文本过滤工具来过滤文本。你还可以把 awk 自身当作一个编程语言。但由于这个指南的适用范围是关于使用 awk 的，我会按照一个简单的命令行过滤工具来介绍它。</p><p>awk 的一般语法如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># awk &#39;script&#39; filename</span></span></code></pre></div><p>此处 <code>&#39;script&#39;</code> 是一个由 awk 可以理解并应用于 filename 的命令集合。</p><p>它通过读取文件中的给定行，复制该行的内容并在该行上执行脚本的方式工作。这个过程会在该文件中的所有行上重复。</p><p>该脚本 <code>&#39;script&#39;</code> 中内容的格式是 <code>&#39;/pattern/ action&#39;</code>，其中 <code>pattern</code> 是一个正则表达式，而 <code>action</code> 是当 awk 在该行中找到此模式时应当执行的动作。</p><h3 id="如何在-linux-中使用-awk-过滤工具" tabindex="-1">如何在 Linux 中使用 awk 过滤工具 <a class="header-anchor" href="#如何在-linux-中使用-awk-过滤工具" aria-label="Permalink to “如何在 Linux 中使用 awk 过滤工具”">​</a></h3><p>在下面的例子中，我们将聚焦于之前讨论过的元字符。</p><h4 id="一个使用-awk-的简单示例" tabindex="-1">一个使用 awk 的简单示例： <a class="header-anchor" href="#一个使用-awk-的简单示例" aria-label="Permalink to “一个使用 awk 的简单示例：”">​</a></h4><p>下面的例子打印文件 /etc/hosts 中的所有行，因为没有指定任何的模式。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># awk &#39;//{print}&#39; /etc/hosts</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/04/Awk-Command-Example.gif" alt=""></p><p><em>awk 打印文件中的所有行</em></p><h4 id="结合模式使用-awk" tabindex="-1">结合模式使用 awk <a class="header-anchor" href="#结合模式使用-awk" aria-label="Permalink to “结合模式使用 awk”">​</a></h4><p>在下面的示例中，指定了模式 <code>localhost</code>，因此 awk 将匹配文件 <code>/etc/hosts</code> 中有 <code>localhost</code> 的那些行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># awk &#39;/localhost/{print}&#39; /etc/hosts</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/04/Use-Awk-Command-with-Pattern.gif" alt=""></p><p><em>awk 打印文件中匹配模式的行</em></p><h4 id="在-awk-模式中使用通配符" tabindex="-1">在 awk 模式中使用通配符 (.) <a class="header-anchor" href="#在-awk-模式中使用通配符" aria-label="Permalink to “在 awk 模式中使用通配符 (.)”">​</a></h4><p>在下面的例子中，符号 <code>(.)</code> 将匹配包含 loc、localhost、localnet 的字符串。</p><p>这里的正则表达式的意思是匹配 <strong>l一个字符c</strong>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># awk &#39;/l.c/{print}&#39; /etc/hosts</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/04/Use-Awk-with-Wild-Cards.gif" alt=""></p><p><em>使用 awk 打印文件中匹配模式的字符串</em></p><h4 id="在-awk-模式中使用字符" tabindex="-1">在 awk 模式中使用字符 (*) <a class="header-anchor" href="#在-awk-模式中使用字符" aria-label="Permalink to “在 awk 模式中使用字符 (*)”">​</a></h4><p>在下面的例子中，将匹配包含 localhost、localnet、lines, capable 的字符串。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># awk &#39;/l*c/{print}&#39; /etc/localhost</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/04/Use-Awk-to-Match-Strings-in-File.gif" alt=""></p><p><em>使用 awk 匹配文件中的字符串</em></p><p>你可能也意识到 <code>(*)</code> 将会尝试匹配它可能检测到的最长的匹配。</p><p>让我们看一看可以证明这一点的例子，正则表达式 <code>t*t</code> 的意思是在下面的行中匹配以 <code>t</code> 开始和 <code>t</code> 结束的字符串：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>this is tecmint, where you get the best good tutorials, how to&#39;s, guides, tecmint.</span></span></code></pre></div><p>当你使用模式 <code>/t*t/</code> 时，会得到如下可能的结果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>this is t</span></span>
<span class="line"><span>this is tecmint</span></span>
<span class="line"><span>this is tecmint, where you get t</span></span>
<span class="line"><span>this is tecmint, where you get the best good t</span></span>
<span class="line"><span>this is tecmint, where you get the best good tutorials, how t</span></span>
<span class="line"><span>this is tecmint, where you get the best good tutorials, how tos, guides, t</span></span>
<span class="line"><span>this is tecmint, where you get the best good tutorials, how tos, guides, tecmint</span></span></code></pre></div><p>在 <code>/t*t/</code> 中的通配符 <code>(*)</code> 将使得 awk 选择匹配的最后一项：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>this is tecmint, where you get the best good tutorials, how to&#39;s, guides, tecmint</span></span></code></pre></div><h4 id="结合集合-character-s-使用-awk" tabindex="-1">结合集合 [ character(s) ] 使用 awk <a class="header-anchor" href="#结合集合-character-s-使用-awk" aria-label="Permalink to “结合集合 [ character(s) ] 使用 awk”">​</a></h4><p>以集合 [al1] 为例，awk 将匹配文件 /etc/hosts 中所有包含字符 a 或 l 或 1 的字符串。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># awk &#39;/[al1]/{print}&#39; /etc/hosts</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/04/Use-Awk-to-Print-Matching-Character.gif" alt=""></p><p><em>使用 awk 打印文件中匹配的字符</em></p><p>下一个例子匹配以 <code>K</code> 或 <code>k</code> 开始头，后面跟着一个 <code>T</code> 的字符串：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># awk &#39;/[Kk]T/{print}&#39; /etc/hosts</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/04/Use-Awk-to-Print-Matched-String-in-File.gif" alt=""></p><p><em>使用 awk 打印文件中匹配的字符</em></p><h4 id="以范围的方式指定字符" tabindex="-1">以范围的方式指定字符 <a class="header-anchor" href="#以范围的方式指定字符" aria-label="Permalink to “以范围的方式指定字符”">​</a></h4><p>awk 所能理解的字符：</p><ul><li><code>[0-9]</code> 代表一个单独的数字</li><li><code>[a-z]</code> 代表一个单独的小写字母</li><li><code>[A-Z]</code> 代表一个单独的大写字母</li><li><code>[a-zA-Z]</code> 代表一个单独的字母</li><li><code>[a-zA-Z 0-9]</code> 代表一个单独的字母或数字</li></ul><p>让我们看看下面的例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># awk &#39;/[0-9]/{print}&#39; /etc/hosts</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/04/Use-Awk-To-Print-Matching-Numbers-in-File.gif" alt=""></p><p><em>使用 awk 打印文件中匹配的数字</em></p><p>在上面的例子中，文件 /etc/hosts 中的所有行都至少包含一个单独的数字 [0-9]。</p><h4 id="结合元字符-使用-awk" tabindex="-1">结合元字符 (^) 使用 awk <a class="header-anchor" href="#结合元字符-使用-awk" aria-label="Permalink to “结合元字符 (^) 使用 awk”">​</a></h4><p>在下面的例子中，它匹配所有以给定模式开头的行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># awk &#39;/^fe/{print}&#39; /etc/hosts</span></span>
<span class="line"><span># awk &#39;/^ff/{print}&#39; /etc/hosts</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/04/Use-Awk-to-Print-All-Matching-Lines-with-Pattern.gif" alt=""></p><p><em>使用 awk 打印与模式匹配的行</em></p><h4 id="结合元字符-使用-awk-1" tabindex="-1">结合元字符 ($) 使用 awk <a class="header-anchor" href="#结合元字符-使用-awk-1" aria-label="Permalink to “结合元字符 ($) 使用 awk”">​</a></h4><p>它将匹配所有以给定模式结尾的行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># awk &#39;/ab$/{print}&#39; /etc/hosts</span></span>
<span class="line"><span># awk &#39;/ost$/{print}&#39; /etc/hosts</span></span>
<span class="line"><span># awk &#39;/rs$/{print}&#39; /etc/hosts</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/04/Use-Awk-to-Print-Given-Pattern-String.gif" alt=""></p><p><em>使用 awk 打印与模式匹配的字符串</em></p><h4 id="结合转义字符-使用-awk" tabindex="-1">结合转义字符 (\\) 使用 awk <a class="header-anchor" href="#结合转义字符-使用-awk" aria-label="Permalink to “结合转义字符 (\\) 使用 awk”">​</a></h4><p>它允许你将该转义字符后面的字符作为文字，即理解为其字面的意思。</p><p>在下面的例子中，第一个命令打印出文件中的所有行，第二个命令中我想匹配具有 $25.00 的一行，但我并未使用转义字符，因而没有打印出任何内容。</p><p>第三个命令是正确的，因为一个这里使用了一个转义字符以转义 $，以将其识别为 &#39;$&#39;（而非元字符）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># awk &#39;//{print}&#39; deals.txt</span></span>
<span class="line"><span># awk &#39;/$25.00/{print}&#39; deals.txt</span></span>
<span class="line"><span># awk &#39;/\\$25.00/{print}&#39; deals.txt</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/04/Use-Awk-with-Escape-Character.gif" alt=""></p><p><em>结合转义字符使用 awk</em></p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>以上内容并不是 awk 命令用做过滤工具的全部，上述的示例均是 awk 的基础操作。在下面的章节中，我将进一步介绍如何使用 awk 的高级功能。感谢您的阅读，请在评论区贴出您的评论。</p><hr>`,81)),n("p",null,[a[1]||(a[1]=t("via: ",-1)),e(s,{href:"http://www.tecmint.com/use-linux-awk-command-to-filter-text-string-in-files/"},{default:i(()=>[...a[0]||(a[0]=[t("http://www.tecmint.com/use-linux-awk-command-to-filter-text-string-in-files/",-1)])]),_:1})]),n("p",null,[a[5]||(a[5]=t("作者：",-1)),e(s,{href:"http://www.tecmint.com/author/aaronkili/"},{default:i(()=>[...a[2]||(a[2]=[t("Aaron Kili",-1)])]),_:1}),a[6]||(a[6]=t(" 译者：",-1)),e(s,{href:"https://github.com/wwy-hust"},{default:i(()=>[...a[3]||(a[3]=[t("wwy-hust",-1)])]),_:1}),a[7]||(a[7]=t(" 校对：",-1)),e(s,{href:"https://github.com/wxy"},{default:i(()=>[...a[4]||(a[4]=[t("wxy",-1)])]),_:1})]),n("p",null,[a[10]||(a[10]=t("本文由 ",-1)),e(s,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...a[8]||(a[8]=[t("LCTT",-1)])]),_:1}),a[11]||(a[11]=t(" 原创编译，",-1)),e(s,{href:"https://linux.cn/"},{default:i(()=>[...a[9]||(a[9]=[t("Linux中国",-1)])]),_:1}),a[12]||(a[12]=t(" 荣誉推出",-1))])])}const y=l(c,[["render",d]]);export{x as __pageData,y as default};
